@app.route('/api/settings/restart', methods=['POST'])
@login_required
def api_restart_server():
    u = current_user(db)
    if not (u.get('role') == 'admin' or user_has(db, u, 'tab.settings') or user_has(db, u, 'action.updater.apply')):
        return jsonify({'success': False, 'error': 'forbidden'}), 403
    import os
    import threading
    import time
    def _do_exit():
        time.sleep(0.6)
        print('=' * 60)
        print('[SERVER] Перезапуск по запросу администратора')
        print('=' * 60)
        os._exit(0)
    threading.Thread(target=_do_exit, daemon=True).start()
    _audit(db, current_user(db), 'update', 'server', 'restart', {})
    return jsonify({'success': True, 'message': 'Сервер завершает работу'})

